export const HERO_MAX_LEVEL=5;
export const HERO_XP=[0,120,320,650,1200];
export function researchCost(player,id) {
 if(id==='harvest')return (player.research?.harvest||0)>=1?[150,120]:[100,80];
 return RESEARCH[id].cost.map(value=>value*((player.research?.[id]||0)+1));
}
export function heroLevelFromXP(xp) {return HERO_XP.reduce((level,threshold,index)=>xp>=threshold?index+1:level,1);}
